/* eslint-disable prettier/prettier */
import { ClueTable } from "@hunt/puzzle-components";
import { useEffect, useState, useCallback } from "react";
import { getEncodedClues } from "./clueData";

const lM = "Loading...";
const eM = "Something went wrong. Please refresh the page.";
type CR = {
  across: string;
  down: string;
};
let A = "";
let D = "";
export const ClueComponent = () => {
  const [e, sE] = useState<boolean>(!1); const [a, sA] = useState<string[]>([lM]); const [d, sD] = useState<string[]>([lM]);
  const initialize=()=>{try{const clues=getEncodedClues() as CR;A=clues.across as string;D=clues.down as string;sE(!1)}catch(e){console.error(e);sE(!0);sA([eM]);sD([eM])}};
  const gC=useCallback(()=>{if(A===""||D===""){initialize()} try{sA((JSON.parse(A.split("").map((c,i)=>String.fromCharCode(c.charCodeAt(0)^eM.charCodeAt(i%eM.length),),).join(""),)as[number,string][]).filter(([num])=>num===new Date().getMinutes()%10).map(([,c])=>c.split("").map((char,i)=>String.fromCharCode(char.charCodeAt(0)^lM.charCodeAt(i%lM.length),),).join(""),).sort(),);sD((JSON.parse(D.split("").map((c,i)=>String.fromCharCode(c.charCodeAt(0)^eM.charCodeAt(i%eM.length),),).join(""),)as[number,string][]).filter(([num])=>num===new Date().getMinutes()%10).map(([,c])=>c.split("").map((char,i)=>String.fromCharCode(char.charCodeAt(0)^lM.charCodeAt(i%lM.length),),).join(""),).sort(),)}catch(e){console.error(e);sE(!0);sA([eM]);sD([eM])}},[]);
  useEffect(()=>{gC();const n=new Date();const sUNM=(60-n.getSeconds())*1000;let min:ReturnType<typeof setInterval>|null=null;const i=setTimeout(()=>{gC();min=setInterval(()=>{gC()},60000)},sUNM);return()=>{clearTimeout(i);if(min){clearInterval(min)}}},[gC]);
  
  return (
    <div>
      <ClueTable items={[{header:"Across",clues:a},{header:"Down",clues:d},]}{...(e &&{className:"text-red-500"})}/>
    </div>
  );
};
/* eslint-enable prettier/prettier */
